class Person {
  // 属性
  name: string;
  age: number;

  // 构造函数
  constructor(name: string, age: number) {
    this.name = name;
    this.age = age;
  }

  // 方法
  greet(): string {
    return `Hello, my name is ${this.name} and I am ${this.age} years old.`;
  }

  // getter
  get isAdult(): boolean {
    return this.age >= 18;
  }

  // setter
  set fullName(name: string) {
    this.name = name;
  }
}

// 创建实例
const person = new Person('Alice', 25);
console.log(person.greet());
console.log('Is adult:', person.isAdult);

person.fullName = 'Alice Smith';
console.log(person.greet());

// 基类
class Animal {
  name: string;

  constructor(name: string) {
    this.name = name;
  }

  makeSound(): string {
    return 'Some generic sound';
  }
}

// 派生类
class Dog extends Animal {
  breed: string;

  constructor(name: string, breed: string) {
    super(name);
    this.breed = breed;
  }

  // 重写方法
  makeSound(): string {
    return 'Woof! Woof!';
  }

  // 新增方法
  fetch(): string {
    return `${this.name} is fetching!`;
  }
}

// 另一个派生类
class Cat extends Animal {
  makeSound(): string {
    return 'Meow!';
  }
}

const animal = new Animal('Generic Animal');
const dog = new Dog('Rex', 'German Shepherd');
const cat = new Cat('Whiskers');

console.log(animal.makeSound());
console.log(dog.makeSound());
console.log(dog.fetch());
console.log(cat.makeSound());

// 接口定义
interface User {
  id: number;
  name: string;
  email: string;
  age?: number; // 可选属性
}

// 使用接口
function createUser(user: User): User {
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    age: user.age
  };
}

// 实现接口
class PremiumUser implements User {
  id: number;
  name: string;
  email: string;
  age?: number;
  membershipLevel: string;

  constructor(id: number, name: string, email: string, membershipLevel: string) {
    this.id = id;
    this.name = name;
    this.email = email;
    this.membershipLevel = membershipLevel;
  }
}

const user1 = createUser({ id: 1, name: 'Alice', email: 'alice@example.com' });
const user2 = new PremiumUser(2, 'Bob', 'bob@example.com', 'gold');

console.log(user1);
console.log(user2);

// 泛型函数
function identity<T>(value: T): T {
  return value;
}

// 泛型类
class Box<T> {
  private value: T;

  constructor(value: T) {
    this.value = value;
  }

  getValue(): T {
    return this.value;
  }

  setValue(value: T): void {
    this.value = value;
  }
}

// 泛型接口
interface Pair<K, V> {
  key: K;
  value: V;
}

// 使用泛型
const numberIdentity = identity<number>(42);
const stringIdentity = identity<string>('Hello');

const numberBox = new Box<number>(100);
const stringBox = new Box<string>('TypeScript');

const pair: Pair<string, number> = { key: 'age', value: 25 };

console.log(numberIdentity);
console.log(stringIdentity);
console.log(numberBox.getValue());
console.log(stringBox.getValue());
console.log(pair);

// 联合类型
type StringOrNumber = string | number;

// 交叉类型
type Person = {
  name: string;
  age: number;
};

type Employee = {
  employeeId: number;
  department: string;
};

type EmployeePerson = Person & Employee;

// 类型守卫
function isString(value: unknown): value is string {
  return typeof value === 'string';
}

// 类型别名
type UserId = string | number;

// 使用高级类型
function processValue(value: StringOrNumber): void {
  if (typeof value === 'string') {
    console.log('String value:', value.toUpperCase());
  } else {
    console.log('Number value:', value * 2);
  }
}

const employee: EmployeePerson = {
  name: 'Alice',
  age: 30,
  employeeId: 1001,
  department: 'Engineering'
};

const userId: UserId = 123;

processValue('Hello');
processValue(42);
console.log(employee);
console.log('User ID:', userId);

// 异步函数
async function fetchData(): Promise<string> {
  // 模拟API调用
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve('Data fetched successfully!');
    }, 1000);
  });
}

// 使用async/await
async function processData() {
  try {
    console.log('Starting to fetch data...');
    const data = await fetchData();
    console.log('Data received:', data);
    return data;
  } catch (error) {
    console.error('Error fetching data:', error);
    throw error;
  }
}

// 并行异步操作
async function fetchMultipleData() {
  const [data1, data2] = await Promise.all([
    fetchData(),
    new Promise<string>((resolve) => setTimeout(() => resolve('Second data'), 500))
  ]);

  console.log('First data:', data1);
  console.log('Second data:', data2);
  return { data1, data2 };
}

// 调用异步函数
processData().then((result) => {
  console.log('Process completed:', result);
});

fetchMultipleData().then((result) => {
  console.log('Multiple data fetched:', result);
});
